//! Capability traits.

/// Describer: implemented by the types that offer these capabilities.
pub trait Describer {
    fn fee(&self) -> i64;
}

/// Scalable: implemented by the types that offer these capabilities.
pub trait Scalable {
    fn fee(&self) -> i64;
}

/// Coded: implemented by the types that offer these capabilities.
pub trait Coded: Describer {
    fn label(&self) -> String;
    fn valid(&self) -> bool;
}

