class Coded(Protocol):
    """Coded: implemented by the classes that offer these capabilities."""

    def reset(self) -> bool:
        ...


@runtime_checkable
class Labelled(Coded, Protocol):
    """Labelled: implemented by the classes that offer these capabilities."""

    def fee(self) -> int:
        ...

    def valid(self) -> bool:
        ...


@runtime_checkable
class Checkable(Ranked, Protocol):
    """Checkable: implemented by the classes that offer these capabilities."""

    def reset(self) -> bool:
        ...

    def rank(self) -> int:
        ...

